#nullable enable // autogenerated

using MVZ2.Vanilla.Properties;
using PVZEngine.Buffs;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using PVZEngine.Timing;
using PVZEngine.Tools.Timing;

namespace MVZ2.GameContent.Buffs.Enemies
{
    /// <summary>
    /// 绝缘：苦力怕在此效果持续期间无法推进自爆倒计时
    /// （charge 不允许增加，但允许因失去目标而减少，避免蓄力中的苦力怕被定在原地）。
    /// 由苦力怕主行为在蓄力分支中检查。
    /// </summary>
    [AutoBuffDefinition(VanillaBuffNames.Enemy.insulated)]
    public class InsulatedBuff : BuffDefinition
    {
        public InsulatedBuff(string nsp, string name) : base(nsp, name)
        {
        }

        public override void OnCreate(Buff buff)
        {
            base.OnCreate(buff);
            buff.SetProperty(PROP_TIMER, TimerHelper.NewSecondTimer(DURATION_SECONDS));
        }

        public override void PostUpdate(Buff buff)
        {
            base.PostUpdate(buff);
            var timer = GetTimer(buff);
            if (timer.RunToExpiredOrNull())
            {
                buff.Remove();
            }
        }

        // 施加/刷新绝缘：重复施加时把持续时间重置为满值
        public static void Apply(Entity entity, float durationSeconds = DURATION_SECONDS)
        {
            var buff = entity.GetFirstBuff<InsulatedBuff>();
            if (buff == null)
            {
                buff = entity.AddBuff<InsulatedBuff>();
            }
            buff.SetProperty(PROP_TIMER, TimerHelper.NewSecondTimer(durationSeconds));
        }

        private static FrameTimer? GetTimer(Buff buff)
        {
            return buff.GetProperty<FrameTimer>(PROP_TIMER);
        }

        public const float DURATION_SECONDS = 30f;
        public static readonly VanillaBuffPropertyMeta<FrameTimer> PROP_TIMER = new VanillaBuffPropertyMeta<FrameTimer>("InsulatedTimer");
    }
}
